const practiceKey='continuumPracticeHistory';
async function api(route,options={}){
 const response=await fetch('/api'+route,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...options});
 const data=await response.json().catch(()=>({error:'Server response unavailable'}));
 if(!response.ok)throw new Error(data.error||`Request failed (${response.status})`);
 return data;
}
function loadPracticeHistory(){
 try{
  const saved=JSON.parse(localStorage.getItem(practiceKey)||'[]');
  if(Array.isArray(saved)&&saved.length)return saved.filter(x=>Number.isFinite(x.score)&&x.score>=0&&x.score<=100).slice(0,2000);
  const old=localStorage.getItem('continuumScore');
  if(old!==null&&Number.isFinite(Number(old)))return [{score:Math.max(0,Math.min(100,Number(old))),total:5,at:null}];
 }catch{}return [];
}

function Ring({value,label}){return <div className="ring" style={{'--p':`${value*3.6}deg`}}><div><b>{value}%</b><span>{uiText(label)}</span></div></div>}
function Metric({item}){return <div className="metric"><div className="metric-top"><span>{item.name}</span><b style={{color:item.color}}>{item.level}</b></div><div className="bar"><i style={{width:`${item.score}%`,background:item.color}}/></div><div className="metric-foot"><span>{item.score}/100</span><span className="up"><TrendingUp size={13}/> {item.delta}</span></div></div>}


function RecentLearning({practiceHistory=[]}){const latest=forLesson(practiceHistory)[0];return <section className="panel activity"><div className="panel-head"><div><span className="eyebrow">{uiText("ONE CONTINUOUS TIMELINE")}</span><h3>{uiText("Recent learning")}</h3></div></div><div className="timeline">
 <div><span className="event-icon ai"><Sparkles size={16}/></span><i/><article><b>{uiText(latest?'Latest practice':'AI practice')}{uiText(" · Subjunctive")}</b><p>{uiText(latest?uiTemplate("{0} questions · {1}% accuracy",[latest.total,latest.score]):'18 questions · 81% accuracy')}</p><small>{uiText(latest?(latest.at?new Date(latest.at).toLocaleString():'Previous practice'):'Today, 18:42')}</small></article></div>
 <div><span className="event-icon class"><Users size={16}/></span><i/><article><b>{uiText("Class with María")}</b><p>{uiText("Conversation: travel & authentic experiences")}</p><small>{uiText("Yesterday, 19:00 · 4 insights captured")}</small></article></div>
 <div><span className="event-icon listen"><Headphones size={16}/></span><article><b>{uiText("Listening practice")}</b><p>{uiText("Airport vlog · B2− comprehension")}</p><small>{uiText("14 Sep · 92% complete")}</small></article></div>
 </div></section>}

function PracticeHistory({attempts}){if(!attempts.length)return null;return <section className="panel practice-log"><span className="eyebrow">{uiText("SELF-STUDY RECORD")}</span><h3>{uiText("Subjunctive practice history")}</h3><div>{attempts.slice(0,5).map((attempt,index)=><article key={`${attempt.at||'previous'}-${index}`}><span>{uiText(attempt.at?new Date(attempt.at).toLocaleString():'Previous attempt')}</span><b>{attempt.score}%</b><small>{attempt.total}{uiText(" questions")}</small></article>)}</div></section>}

