 const makeCode=async()=>{if(busy)return;setBusy(true);setError('');try{const x=await api('/share-code',{method:'POST',body:JSON.stringify({language:codeLanguage})});setCode(x.code)}catch(e){setError(e.message)}finally{setBusy(false)}};
