function ConnectedTeacher({section='Overview',onNavigate,user}){
 const storedContext=()=>{try{return JSON.parse(sessionStorage.getItem('continuumTeachingContext:'+user.id)||'{}')}catch{return {}}};
 const [viewLanguage,setViewLanguage]=useState(()=>storedContext().language||'');
 const [learners,setLearners]=useState([]),[selected,setSelected]=useState(()=>storedContext().learnerId||''),[record,setRecord]=useState(null),[notes,setNotes]=useState([]),[code,setCode]=useState(''),[noteLanguage,setNoteLanguage]=useState('es'),[focus,setFocus]=useState('Subjunctive'),[note,setNote]=useState(''),[message,setMessage]=useState(''),[error,setError]=useState(''),[saving,setSaving]=useState(false);
 const sharedLanguages=learners.find(l=>l.id===selected)?.languages||[],language=sharedLanguages.includes(viewLanguage)?viewLanguage:sharedLanguages[0]||'';
 useEffect(()=>{if(selected&&language)sessionStorage.setItem('continuumTeachingContext:'+user.id,JSON.stringify({learnerId:selected,language}))},[selected,language]);
 const refresh=async()=>{const r=await api('/teacher/learners');setLearners(r.learners);setSelected(id=>id&&r.learners.some(x=>x.id===id)?id:r.learners[0]?.id||'')};
 useEffect(()=>{refresh().catch(e=>setError(e.message));const timer=setInterval(()=>refresh().catch(()=>{}),15000);return()=>clearInterval(timer)},[]);
 useEffect(()=>{let live=true;setRecord(null);setNotes([]);setNote('');setNoteLanguage(language);setFocus('Class practice');setError('');
  if(!selected||!language)return;
  const load=()=>Promise.all([api('/teacher/learners/'+selected+'?language='+language),api('/teacher/learners/'+selected+'/notes?language='+language)]).then(([a,b])=>{if(live){setRecord(a);setNotes(b.notes)}}).catch(e=>{if(live){setRecord(null);setNotes([]);setError(e.message)}});
  load();const timer=setInterval(load,15000);return()=>{live=false;clearInterval(timer)};
 },[selected,language]);
 const connect=async e=>{e.preventDefault();setError('');try{await api('/teacher/connect',{method:'POST',body:JSON.stringify({code})});setCode('');setMessage('Learner connected.');await refresh()}catch(err){setError(err.message)}};
 const save=async e=>{e.preventDefault();if(!selected||saving)return;setError('');setSaving(true);try{const r=await api('/teacher/learners/'+selected+'/notes',{method:'POST',body:JSON.stringify({focus,note,language:noteLanguage})});setNotes(list=>[{...r.note,teacher:'You'},...list]);setNote('');setMessage('Class note saved to this learner’s account.')}catch(err){setError(err.message)}finally{setSaving(false)}};
 return <>{section==='Overview'&&<TeacherInsights compact onSchedule={()=>onNavigate('Schedule')} onClasses={()=>onNavigate('Teaching insights')}/>} {message&&<p className="auth-success" role="status">{message}</p>}{error&&<p className="auth-error" role="alert">{uiText(error)}</p>}
 {section==='Overview'&&<div className="teacher-roster">{learners.map(l=><button key={l.id} className={selected===l.id?'selected':''} onClick={()=>{setRecord(null);setSelected(l.id)}}><b>{l.name}</b><span className="learner-plan">{uiText(l.membership?.tier==='premium'?'Premium':'Free')}</span><small>{l.languages.map(id=>uiText(languageInfo(id).name)).join(' · ')}</small></button>)}</div>}{section==='Overview'&&<section className="panel connect-code"><div><h2>{uiText("Connect a learner")}</h2><p>{uiText("Ask the learner to generate a one-time code in Account.")}</p></div><form onSubmit={connect}><input aria-label={uiText("Learner sharing code")} value={code} onChange={e=>setCode(e.target.value.toUpperCase())} placeholder={uiText("12-character code")} maxLength={12} required/><button className="primary">{uiText("Connect")}</button></form></section>}
 {learners.length===0?<><PageIntro eyebrow="CONNECTED TEACHER VIEW" title={uiText("Your learners")} text="Connect a learner to see their saved results and record class observations."/><section className="panel empty-learner"><Users size={25}/><h2>{uiText("No learners connected yet")}</h2><p>{uiText("Enter a sharing code on Overview after your learner creates one in Account.")}</p>{section!=='Overview'&&<button className="primary" onClick={()=>onNavigate('Overview')}>{uiText("Go to Overview")}</button>}</section></>:<>
 <div className="learner-picker"><label htmlFor="choose-learner">{uiText("Viewing learner")}</label><select id="choose-learner" disabled={saving} value={selected} onChange={e=>{setMessage('');setError('');setNote('');setFocus('Class practice');setRecord(null);setNotes([]);setSelected(e.target.value)}}>{learners.map(x=><option value={x.id} key={x.id}>{x.name}</option>)}</select></div><div className="learner-picker"><label htmlFor="teacher-view-language">{uiText("Shared lesson language")}</label><select id="teacher-view-language" value={language} disabled={!sharedLanguages.length||saving} onChange={e=>{setRecord(null);setNotes([]);setViewLanguage(e.target.value)}}>{!sharedLanguages.length&&<option value="">{uiText("No language shared")}</option>}{languages.filter(l=>sharedLanguages.includes(l.id)).map(l=><option key={l.id} value={l.id}>{uiText(l.name)}</option>)}</select><small>{uiText("Only this language’s learning records are shown.")}</small></div>
 {record?.membership&&<p className="learner-plan">{uiText('Learner membership')}: {uiText(record.membership.tier==='premium'?'Premium':'Free')}</p>}
 {record?.sharing?.selfLearning===false&&<div className="privacy-banner"><Users size={18}/><div><b>{uiText("Self-study activity is private")}</b><p>{uiText("This learner has hidden lesson activity, scores and assessment results. Class notes and your connection are still available.")}</p></div></div>}
 {!language?<section className="panel"><h2>{uiText("Language access has not been set")}</h2><p>{uiText("Ask the learner to select the language they study with you in Account → Connected teachers. Learning records remain hidden until then.")}</p></section>:!record?<section className="panel account-loading">{uiText(error?'Shared record unavailable. Check the learner’s language sharing settings.':'Loading learner record…')}</section>:section==='Full report'?<TeacherReportLive record={record} onNavigate={onNavigate}/>:section==='Assignments'?<ClassWorkspace key={selected+language} user={user} initialLearner={selected} initialLanguage={language} initialTab="assignments" onAccount={()=>onNavigate('Account')}/>:section==='Learning memory'?<TeacherMemoryLive key={selected+language} record={record} notes={notes} onNavigate={onNavigate}/>:section==='Class notes'?<TeacherNotesLive user={user} onNotesChanged={async()=>{const r=await api('/teacher/learners/'+selected+'/notes?language='+language);setNotes(r.notes)}} noteLanguage={noteLanguage} setNoteLanguage={setNoteLanguage} record={record} notes={notes} focus={focus} setFocus={setFocus} note={note} setNote={setNote} onSave={save} onNavigate={onNavigate} saving={saving}/>:<TeacherOverviewLive record={record} notes={notes} onNavigate={onNavigate}/>}
 {record&&record.sharing?.selfLearning!==false&&['Class notes','Learning memory','Full report'].includes(section)&&<SkillRecord key={selected+'-'+section+'-'+language} learnerId={selected} language={language}/>}
 </>}</>;
}

