 useEffect(()=>{const revision=++accountRevision.current;api('/auth/me').then(async r=>{if(revision!==accountRevision.current)return;if(r.user){setUser(r.user);setRole(r.user.role);if(r.user.role==='learner'){const [p,n]=await Promise.all([api('/practice'),api('/notes')]);if(revision===accountRevision.current){setPracticeHistory(p.attempts);setNotes(n.notes)}}}else setPracticeHistory(loadPracticeHistory())}).catch(e=>{if(revision!==accountRevision.current)return;setAuthError('Account service unavailable: '+e.message);setPracticeHistory(loadPracticeHistory())}).finally(()=>{if(revision===accountRevision.current)setAuthReady(true)})},[]);
 useEffect(()=>{if(authReady&&!user){localStorage.setItem(practiceKey,JSON.stringify(practiceHistory));if(practiceHistory[0])localStorage.setItem('continuumScore',String(forLesson(practiceHistory)[0]?.score??0))}},[practiceHistory,user,authReady]);
 useEffect(()=>{let live=true;setProfileRecord(null);setProfileError('');setProfileReady(!user);if(user)profileRequest('/profile').then(r=>{if(!live)return;setProfileRecord(r);setProfileReady(true);setWelcome(false);if(user.role==='learner'&&r.profile){const p=r.profile;if(!localStorage.getItem('continuumLanguage')){setLanguage(p.primaryLanguage);localStorage.setItem('continuumLanguage',p.primaryLanguage)}const key='continuumCourseLevel'+(p.primaryLanguage==='es'?'':':'+p.primaryLanguage);if(!localStorage.getItem(key))localStorage.setItem(key,p.level)}}).catch(e=>{if(live)setProfileError(e.message)});return()=>{live=false}},[user?.id,profileRetry]);
 useEffect(()=>{let live=true;if(user?.role!=='learner')return;const load=()=>{if(document.hidden)return;api('/notes').then(d=>{if(live)setNotes(d.notes)}).catch(()=>{})};load();const timer=setInterval(load,20000);window.addEventListener('classroom-updated',load);return()=>{live=false;clearInterval(timer);window.removeEventListener('classroom-updated',load)}},[user?.id,tab]);
